import re
import sys

assignment = re.compile(r"\s*(TMP|[a-p])\s*<-\s*(.*?)\s*;\s*")
addition = re.compile(r"\(\s*(TMP|[a-p])\s*\+\s*(\d+)\s*\)\s*mod\s*100")
number = re.compile(r"\d+")

values = {}

for line in sys.stdin:
    if line.lstrip().startswith("//"):
        continue

    match = assignment.fullmatch(line)
    if not match:
        continue

    name, expression = match.groups()
    if number.fullmatch(expression):
        values[name] = int(expression)
    else:
        update = addition.fullmatch(expression)
        if update is None or update.group(1) != name:
            raise ValueError(f"Invalid assignment: {line.strip()}")
        values[name] = (values[name] + int(update.group(2))) % 100

names = [*("abcdefghijklmnop"), "TMP"]
print("; ".join(f"{name} ?= {values[name]}" for name in names) + ";")
